using ProjetoIntegradorBack.Domain.Entities; using ProjetoIntegradorBack.Domain.Enums; using ProjetoIntegradorBack.Domain.Interfaces; using ProjetoIntegradorBack.Infrastructure.Context; using ProjetoIntegradorBack.Shared.Pattern; using Microsoft.EntityFrameworkCore;
namespace ProjetoIntegradorBack.Infrastructure.Repositories;
public class ContatoRepository(ProjetoIntegradorBackDbContext context):IContatoRepository{
public async Task<Result<Contato>> AdicionarAsync(Contato e,CancellationToken ct=default){try{e.Id=Guid.NewGuid();e.CriadoEm=DateTime.UtcNow;await context.Contatos.AddAsync(e,ct);await context.SaveChangesAsync(ct);return Result<Contato>.AsSuccess(e);}catch(Exception ex){return Result<Contato>.AsFailure(new Failure(500,ex.Message));}}
public async Task<Result<IReadOnlyList<Contato>>> ListarAsync(StatusContato? status,int pagina,int tamanho,CancellationToken ct=default){try{var q=context.Contatos.AsQueryable();if(status.HasValue)q=q.Where(x=>x.Status==status);return Result<IReadOnlyList<Contato>>.AsSuccess(await q.OrderByDescending(x=>x.CriadoEm).Skip((pagina-1)*tamanho).Take(tamanho).ToListAsync(ct));}catch(Exception ex){return Result<IReadOnlyList<Contato>>.AsFailure(new Failure(500,ex.Message));}}
public async Task<Result<int>> ContarAsync(StatusContato? status,CancellationToken ct=default){try{var q=context.Contatos.AsQueryable();if(status.HasValue)q=q.Where(x=>x.Status==status);return Result<int>.AsSuccess(await q.CountAsync(ct));}catch(Exception ex){return Result<int>.AsFailure(new Failure(500,ex.Message));}}
public async Task<Result<Contato>> AtualizarStatusAsync(Guid id,StatusContato status,CancellationToken ct=default){try{var e=await context.Contatos.FindAsync(new object[]{id},ct);if(e==null)return Result<Contato>.AsFailure(new Failure(404,"Contato não encontrado."));e.Status=status;await context.SaveChangesAsync(ct);return Result<Contato>.AsSuccess(e);}catch(Exception ex){return Result<Contato>.AsFailure(new Failure(500,ex.Message));}}}